#| 0, 1, ..., n - 1.
def py_iota(n) {
    a = zeros(n)
    for i to n {
        a[i] = i
    }
    return a
}

#| Every entry of a real array, row-major, as a vector (a copy).
def py_flat(a: Arr) {
    return take(a, py_iota(numel(a)))
}

#| A copy of a real array (np.copy, a.copy(), np.array(a)).
def py_copy(a: Arr) {
    return a * 1.0
}

#| np.arange(start, stop, step), as NumPy fills it: ceil((stop - start) / step) entries,
#| entry k = start + k * delta with delta = (start + step) - start.
def py_arange(start, stop_, step) {
    if step == 0 {
        stop("ZeroDivisionError: division by zero")
    }
    if not (abs((stop_ - start) / step) < 1.0 / 0.0) {
        stop("py2viv: np.arange of a length that is not finite (NumPy raises ValueError)")
    }
    n = max(ceil((stop_ - start) / step), 0)
    a = zeros(n)
    delta = (start + step) - start
    for k to n {
        a[k] = start + k * delta
    }
    return a
}

#| np.argmax(a): the flat index of the first largest entry.
def py_argmax(a: Arr) {
    f = py_flat(a)
    k = 0
    if f[0] != f[0] {
        return 0
    }
    for i from 1 to len(f) {
        if f[i] != f[i] {
            return i
        }
        if f[i] > f[k] {
            k = i
        }
    }
    return k
}

#| np.linalg.solve(A, b) for a vector b. Viv's lin_solve(A, b, x) writes x and returns 0.
def py_solve(A: Arr, b: Arr) {
    if not (all(abs(A) < 1.0 / 0.0) and all(abs(b) < 1.0 / 0.0)) {
        stop("py2viv: np.linalg.solve with a NaN or an infinity (LAPACK's answer is its own)")
    }
    x = zeros(len(b))
    lin_solve(A, b, x)
    if all(abs(A) < 1.0 / 0.0) and all(abs(b) < 1.0 / 0.0) and not all(abs(x) < 1.0 / 0.0) {
        stop("numpy.linalg.LinAlgError: Singular matrix")
    }
    return x
}

#| An int result, as Python's int: a -0.0 becomes 0 (an int has no sign on zero), and the run
#| stops at 2^53, past which a double no longer holds every integer (Python's int does).
def py_int(x) {
    if abs(x) >= 9007199254740992 {
        stop("py2viv: an integer reached 2^53; Python's int is exact there and a double is not")
    }
    return x + 0.0
}

#| a / b with a float: ZeroDivisionError on a zero divisor.
def py_div_f(a, b) {
    if b == 0 {
        stop("ZeroDivisionError: float division by zero")
    }
    return a / b
}

#| np.isclose(a, b, rtol, atol) of two numbers: |a - b| <= atol + rtol |b| when both are
#| finite, a == b otherwise (a NaN is never close).
def py_npisclose(a, b, rtol, atol) {
    if abs(a) < 1.0 / 0.0 and abs(b) < 1.0 / 0.0 {
        return abs(a - b) <= atol + rtol * abs(b)
    }
    return a == b
}

#| np.allclose(a, b, rtol, atol) of two arrays of one shape: np.isclose entry by entry.
def py_allclose(a: Arr, b: Arr, rtol, atol) {
    fa = py_flat(a)
    fb = py_flat(b)
    if len(fa) != len(fb) {
        stop("py2viv: np.allclose of two arrays of different sizes (NumPy broadcasts them)")
    }
    for i to len(fa) {
        if not py_npisclose(fa[i], fb[i], rtol, atol) {
            return false
        }
    }
    return true
}

#| A slice bound as Python reads it on an axis of length n: a negative one counts from the
#| end; the result is clamped to 0 ... n.
def py_lo(lo, n) {
    b = lo
    if b < 0 {
        b = b + n
        if b < 0 {
            b = 0
        }
    }
    if b > n {
        b = n
    }
    return b
}

#| An index next to a slice, as NumPy reads it on an axis of length n: a negative one counts
#| from the end (one still out of bounds stops the run, as NumPy raises IndexError).
def py_ix(i, n) {
    if i < 0 {
        return i + n
    }
    return i
}

#| The shape NumPy broadcasts two shapes da and db to (aligned at the last axis, a length 1
#| stretched); the run stops where NumPy raises ValueError.
def py_bdims(da: Arr, db: Arr) {
    n = len(da)
    if len(db) > n {
        n = len(db)
    }
    e = zeros(n)
    for i to n {
        x = 1
        y = 1
        if i >= n - len(da) {
            x = da[i - n + len(da)]
        }
        if i >= n - len(db) {
            y = db[i - n + len(db)]
        }
        if x == y or y == 1 {
            e[i] = x
        }
        else {
            if x == 1 {
                e[i] = y
            }
            else {
                stop("ValueError: operands could not be broadcast together with shapes")
            }
        }
    }
    return e
}

#| The flat indices, in row-major order of the shape e, of the entries of an array of shape d
#| that broadcasting to e reads (a length 1 of d is read again along that axis of e).
def py_bidx(d: Arr, e: Arr) {
    n = len(e)
    m = len(d)
    st = zeros(n)
    s = 1
    for k to m {
        j = m - 1 - k
        if d[j] != 1 {
            st[j + n - m] = s
        }
        s = s * d[j]
    }
    idx = zeros(1)
    for i to n {
        w = e[i]
        nxt = zeros(len(idx) * w)
        for p to len(idx) {
            for c to w {
                nxt[p * w + c] = idx[p] + c * st[i]
            }
        }
        idx = nxt
    }
    return idx
}

#| a broadcast to the shape e (a shape py_bdims gave for a and another array): a itself when
#| it has that shape, else a new array whose entries are copies of a's.
def py_bto(a: Arr, e: Arr) {
    d = shape(a)
    if len(d) == len(e) {
        if all(d == e) {
            return a
        }
    }
    return py_shaped(take(a, py_bidx(d, e)), e)
}

#| a - b of two real arrays, broadcast.
def py_bsub(a: Arr, b: Arr) {
    e = py_bdims(shape(a), shape(b))
    return py_bto(a, e) - py_bto(b, e)
}

#| The result r of `x += v` (and -=, *=, /=), which NumPy writes into x: the run stops where
#| broadcasting made r larger than x (NumPy raises ValueError).
def py_inpl(r: Arr, x: Arr) {
    if len(shape(r)) != len(shape(x)) {
        stop("ValueError: non-broadcastable output operand with shape")
    }
    if any(shape(r) != shape(x)) {
        stop("ValueError: non-broadcastable output operand with shape")
    }
    return r
}

#| 1 when a value of shape dv broadcasts to exactly the shape e (each of its lengths,
#| aligned at the last axis, is e's or 1), else 0.
def py_bfits(dv: Arr, e: Arr) {
    n = len(e)
    m = len(dv)
    if m > n {
        return 0
    }
    for k to m {
        x = dv[m - 1 - k]
        if x != 1 and x != e[n - 1 - k] {
            return 0
        }
    }
    return 1
}

#| One entry of an integer index array on an axis of length n: a negative one counts from the
#| end; NumPy raises IndexError for one out of bounds.
def py_ixchk(i, n) {
    j = i
    if j < 0 {
        j = j + n
    }
    if j < 0 or j >= n {
        stop("IndexError: index")
    }
    return j
}

#| a with an integer index array idx on axis k (the other axes whole): the result's shape is
#| a's with axis k replaced by idx's shape; a negative index counts from the end.
def py_gath(a: Arr, idx: Arr, k) {
    s = py_ax(a, k)
    before = s[0]
    along = s[1]
    after = s[2]
    f = py_flat(idx)
    for q to len(f) {
        f[q] = py_ixchk(f[q], along)
    }
    src = zeros(before * len(f) * after)
    p = 0
    for o to before {
        for q to len(f) {
            for i to after {
                src[p] = (o * along + f[q]) * after + i
                p += 1
            }
        }
    }
    d = shape(a)
    di = shape(idx)
    e = []
    for t to k {
        e = append(e, d[t])
    }
    for t to len(di) {
        e = append(e, di[t])
    }
    for t from k + 1 to len(d) {
        e = append(e, d[t])
    }
    return py_shaped(take(a, src), e)
}

#| The entries a store through integer indices writes: v broadcast to the shape e of the
#| indexed result, row-major; NumPy raises ValueError where v does not broadcast to e.
def py_vals(v: Arr, e: Arr) {
    if py_bfits(shape(v), e) == 0 {
        stop("ValueError: shape mismatch: value array of shape")
    }
    return py_flat(py_bto(v, e))
}

#| a[..., idx, ...] = v with an integer index array idx on axis k (the other axes whole):
#| the entries of v (broadcast) written in row-major order of the indexed result, so of
#| repeated indices the last write wins.
def py_setax(a: Arr, idx: Arr, k, v: Arr) {
    s = py_ax(a, k)
    before = s[0]
    along = s[1]
    after = s[2]
    f = py_flat(idx)
    for q to len(f) {
        f[q] = py_ixchk(f[q], along)
    }
    dst = zeros(before * len(f) * after)
    p = 0
    for o to before {
        for q to len(f) {
            for i to after {
                dst[p] = (o * along + f[q]) * after + i
                p += 1
            }
        }
    }
    d = shape(a)
    di = shape(idx)
    e = []
    for t to k {
        e = append(e, d[t])
    }
    for t to len(di) {
        e = append(e, di[t])
    }
    for t from k + 1 to len(d) {
        e = append(e, d[t])
    }
    put(a, dst, py_vals(v, e))
    return 0
}

#| np.allclose(a, b, rtol, atol) of two arrays, broadcast.
def py_ballclose(a: Arr, b: Arr, rtol, atol) {
    e = py_bdims(shape(a), shape(b))
    return py_allclose(py_bto(a, e), py_bto(b, e), rtol, atol)
}

#| The sizes around axis k of a (k = -1: every axis, the array flat): [before, along, after].
def py_ax(a: Arr, k) {
    d = shape(a)
    if k < 0 {
        return [1, numel(a), 1]
    }
    before = 1
    for i to k {
        before = before * d[i]
    }
    after = 1
    for i from k + 1 to len(d) {
        after = after * d[i]
    }
    return [before, d[k], after]
}

#| The entries of f, row-major, as an array of shape e (a vector of 1 to 4 lengths).
def py_shaped(f: Arr, e: Arr) {
    if len(e) == 1 {
        return f
    }
    if len(e) == 2 {
        z = zeros(e[0], e[1])
    }
    else {
        if len(e) == 3 {
            z = zeros(e[0], e[1], e[2])
        }
        else {
            z = zeros(e[0], e[1], e[2], e[3])
        }
    }
    put(z, py_iota(numel(z)), f)
    return z
}

