# @@ LU factorization with partial pivoting
def lu_factor(A: Arr) {
    n = len(A)
    LU = py_copy(A)
    perm = py_arange(0, n, 1)
    for k to py_int(n - 1) {
        p = py_int(k + py_argmax(abs(LU[py_lo(k, len(LU)):, py_ix(k, shape(LU)[1])])))
        if p != k {
            py_setax(LU, [k, p], 0, py_gath(LU, [p, k], 0))
            py_setax(perm, [k, p], 0, py_gath(perm, [p, k], 0))
        }
        for i from py_int(k + 1) to n {
            LU[i, k] /= LU[k, k]
            LU[py_ix(i, len(LU)), py_lo(py_int(k + 1), shape(LU)[1]):] = py_inpl(py_bsub(LU[py_ix(i, len(LU)), py_lo(py_int(k + 1), shape(LU)[1]):], LU[i, k] * LU[py_ix(k, len(LU)), py_lo(py_int(k + 1), shape(LU)[1]):]), LU[py_ix(i, len(LU)), py_lo(py_int(k + 1), shape(LU)[1]):])
        }
    }
    return LU, perm
}
# @@ forward and back substitution
def lu_solve(LU: Arr, perm: Arr, b: Arr) {
    n = len(b)
    y = py_copy(py_gath(b, perm, 0))
    for i to n {
        y[i] -= sum(LU[py_ix(i, len(LU)), :py_lo(i, shape(LU)[1])] * y[:py_lo(i, len(y))])
    }
    x = py_copy(y)
    for i to n reversed {
        x[i] = py_div_f(x[i] - sum(LU[py_ix(i, len(LU)), py_lo(py_int(i + 1), shape(LU)[1]):] * x[py_lo(py_int(i + 1), len(x)):]), LU[i, i])
    }
    return x
}
# @@ solve a system
A = [[2.0, 1.0, 1.0], [4.0, -6.0, 0.0], [-2.0, 7.0, 2.0]]
b = [5.0, -2.0, 9.0]
LU, perm = lu_factor(A)
x = lu_solve(LU, perm, b)
print("pivot order", fmt(perm, "d"))
print("x =", fmt(x))
# @@ against the library solver
x_lib = py_solve(A, b)
print("library x =", fmt(x_lib))
# @@ checks
if not (py_ballclose(A @ x, b, 1e-05, 1e-12)) {
    stop("AssertionError")
}
if not (py_ballclose(x, x_lib, 1e-05, 1e-12)) {
    stop("AssertionError")
}
